window.AUTH=window.AUTH||{};window.AUTH["23-621"]={"d":"23-621","id":"2024/23-621","n":"Lackey v. Stinnie","briefs":[{"k":"petitioner","label":"Brief of petitioner Gerald F. Lackey, in his Official Capacity as the Commissioner of the Virginia Department of Motor Vehicles","date":"2024-06-20","url":"https://www.supremecourt.gov/DocketPDF/23/23-621/315393/20240620153253332_Stinnie%20Merits%20Brief_Final.pdf","side":"pet","n":92},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-06-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-621/315928/20240627170049395_23-621tsacUnitedStates.pdf","side":"us","n":52},{"k":"respondent","label":"Brief of respondents Damian Stinnie, et al.","date":"2024-08-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-621/321642/20240805142922078_Stinnie%20-%20Brief%20for%20Respondents%208.5.2024%20Final.pdf","side":"res","n":103},{"k":"reply","label":"Reply of petitioner Gerald F. Lackey, in his Official Capacity as the Commissioner of the Virginia Department of Motor Vehicles","date":"2024-09-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-621/324073/20240904131704745_Stinnie%20Reply%20Brief_final.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r12_8njq.pdf","tr":true,"items":[{"t":"case","label":"Advantage Media, L.L.C. v. City of Hopkins, Minn.","cite":"511 F.3d 833","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/511/833/","by":{"0":"35"}},{"t":"case","label":"Alliance for the Wild Rockies v. Cottrell","cite":"632 F.3d 1127","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/632/1127/","by":{"0":"25"}},{"t":"case","label":"Alyeska Pipeline Serv. Co. v. Wilderness Soc’y","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"op":6,"ar":2,"sum":"Under the \"American Rule\" that attorneys' fees are not ordinarily recoverable by the prevailing litigant in federal litigation in the absence of statutory authorization, respondents, which had instituted litigation to prevent issuance of Government permits required for construction of the trans-Alaska oil pipeline, cannot recover attorneys' fees from petitioner based on the \"private attorney general\" approach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"13, 23, 24","2":"3"}},{"t":"case","label":"Amawi v. Paxton","cite":"48 F.4th 412","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/48/412/","by":{"0":"42"}},{"t":"case","label":"American Libr. Ass’n v. Barr","cite":"956 F.2d 1178","y":1992,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/956/1178/","by":{"0":"50"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"0":"16, 26","1":"13, 14"}},{"t":"case","label":"Board of Trustees of Glazing Health & Welfare Tr. v. Chambers","cite":"941 F.3d 1195","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/941/1195/","op":1,"by":{"0":"51"}},{"t":"case","label":"Borden v. United States","cite":"593 U.S. 420","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"16"}},{"t":"case","label":"Bradley v. Richmond School Board","cite":"416 U.S. 696","y":1974,"id":"1973/72-1322","sc":1,"op":1,"ar":4,"sum":"Section 718 can be applied to attorneys' services that were rendered before that provision was enacted, in a situation like the one here involved where the propriety of the fee award was pending resolution on appeal when the statute became law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"18","2":"18-19"}},{"t":"case","label":"Buckhannon Bd. & Care Home, Inc. v. West Va. Dep’t of Health & Human Res.","cite":"532 U.S. 598","y":2001,"id":"2000/99-1848","sc":1,"op":21,"ar":15,"sum":"The Court held that the \"catalyst theory\" is not a permissible basis for the award of attorney's fees under the FHAA and ADA. \"In the United States, parties are ordinarily required to bear their own attorney's fees -- the prevailing party is not entitled to collect from the loser,\" wrote Chief Justice Rehnquist, \"[u]nder this 'American Rule,' we follow 'a general practice of not awarding fees to a prevailing party absent explicit statutory authority.'\" Dissenting, Justice Ruth Bader Ginsburg argued that \"Congress prescribed fee-shifting provisions like those included in the FHAA and ADA to encourage private enforcement of laws designed to advance civil rights.","sumSrc":"Oyez","by":{"0":"2, 3, 13-17, 19-22, 33-35, 39, 41-43, 45-49, 52-54","1":"7, 12-16, 18-20, 30, 32","2":"15-16, 22, 26-27, 31, 33, 39, 42, 46, 48-50","3":"1, 4, 5, 6, 7, 9, 11, 14, 15, 19, 21, 22, 23, 25"}},{"t":"case","label":"Campaign for Fam. Farms v. Glickman","cite":"200 F.3d 1180","y":2000,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/200/1180/","by":{"0":"52"}},{"t":"case","label":"Chicago United Indus., Ltd. v. City of Chicago","cite":"445 F.3d 940","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/445/940/","by":{"0":"39"}},{"t":"case","label":"City of Burlington v. Dague","cite":"505 U.S. 557","y":1992,"id":"1991/91-810","sc":1,"sum":"The fee-shifting statutes at issue do not permit enhancement of a fee award beyond the lodestar amount to reflect the fact that a party's attorneys were retained on a contingent-fee basis. In Pennsylvaniav. Delaware Valley Citizens' Council for Clean Air, 483 U. S. 711 (Delaware Valley II), this Court addressed, but did not resolve, a question essentially identical to the one presented here. The position taken by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"sum":"The Court found that the President did not have immunity from civil litigation.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Cuomo v. Clearing House Ass’n, L.L.C.","cite":"557 U.S. 519","y":2009,"id":"2008/08-453","sc":1,"sum":"The Court found that state officials are not precluded from regulating and enforcing banking activities governed by the Office of the Comptroller.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Curtis v. Thompson","cite":"840 F.2d 1291","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/840/1291/","by":{"0":"25"}},{"t":"case","label":"Dearmore v. City of Garland","cite":"519 F.3d 517","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/519/517/","op":1,"by":{"0":"13, 41, 42, 47"}},{"t":"case","label":"DiMartile v. Hochul","cite":"80 F.4th 443","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/80/443/","by":{"0":"47","3":"14, 15, 18, 19"}},{"t":"case","label":"Dixon v. Love","cite":"431 U.S. 105","y":1977,"id":"1976/75-1513","sc":1,"sum":"The Illinois statute, as implemented by the Secretary's regulations, is constitutionally adequate under the Due Process Clause of the Fourteenth Amendment, as analyzed in Mathews v. Eldrzdge, 424 U. S. 319, 333.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Dupuy v. Samuels","cite":"423 F.3d 714","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/423/714/","op":1,"by":{"0":"38, 44, 48","3":"18"}},{"t":"case","label":"Evans v. Jeff D.","cite":"475 U.S. 717","y":1986,"id":"1985/84-1288","sc":1,"sum":"The Civil Rights Attorney's Fees Awards Act of 1976 (Fees Act) provides that \"the court, in its discretion, may allow the prevailing party... a reasonable attorney's fee\" in enumerated civil rights actions. Respondents brought a class action against petitioners (the Governor and other public officials of Idaho responsible for the education and treatment of mentally handicapped children) in Federal District Court on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49, 50","2":"48"}},{"t":"case","label":"Farrar v. Hobby","cite":"506 U.S. 103","y":1992,"id":"1992/91-990","sc":1,"op":6,"sum":"Petitioners, coadministrators of decedent Farrar's estate, sought $17 million in compensatory damages, pursuant to 42 U. S. C. §§ 1983 and 1985, from respondent Hobby and other Texas public officials for the alleged illegal closure of the school that Farrar and his son operated. However, the Federal District Court awarded them only nominal damages and, subsequently, awarded them $280,000 in attorney's fees under 42 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 21","1":"15, 16, 21, 22","2":"22, 27, 33, 53","3":"1, 6, 7, 14, 24"}},{"t":"case","label":"Federal Sav. & Loan Ins. Corp. v. Dixon","cite":"835 F.2d 554","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/554/","by":{"0":"23"}},{"t":"case","label":"Fleischmann Distilling Corp. v. Maier Brewing Co.","cite":"386 U.S. 714","y":1967,"id":"1966/214","sc":1,"sum":"Attorney's fees are not recoverable under the Lanham Act. The meticulous statutory provisions set forth in § 35 are exclusive of any other monetary remedies for violation of rights protected by the Act. Pp. 717-721. 359 F. 2d 156, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53","1":"23"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Foreman v. Dallas Cnty.","cite":"193 F.3d 314","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/193/314/","by":{"0":"43"}},{"t":"case","label":"Fowler v. Benson","cite":"924 F.3d 247","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/924/247/","sum":"Noting that “[p]erhaps Plaintiffs are right that the policy [of suspending driver’s licenses due to unpaid court debt] is unwise, even counterproductive,” but that “misguided laws may nonetheless be constitutional” (citation omitted).","sumSrc":"brief:0","by":{"0":"28, 29, 30, 49","2":"35","3":"11, 12"}},{"t":"case","label":"Fowler v. Johnson","cite":"2017 WL 6379676","y":2017,"court":"E.D. Mich. Dec. 14","by":{"0":"7, 28"}},{"t":"case","label":"Getir US, Inc. v. Doe","cite":"2023 WL 3898933","y":2023,"court":"E.D. Va. June 8","by":{"0":"30"}},{"t":"case","label":"Glaxo Grp., Ltd. v. Apotex, Inc.","cite":"376 F.3d 1339","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1339/","by":{"0":"26"}},{"t":"case","label":"Green Haven Prison Preparative Meeting of the Religious Soc’y of Friends v. New York State Dep’t of Corr. & Cmty. Supervision","cite":"16 F.4th 67","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/16/67/","by":{"0":"25"}},{"t":"case","label":"Hanrahan v. Hampton","cite":"446 U.S. 754","y":1980,"id":"1979/79-912","sc":1,"op":5,"ar":7,"sum":"Respondents were not \"prevailing\" parties in the sense intended by the Act. While Congress contemplated the award of fees pendente lite in some cases, it intended to permit such an interlocutory award only when a party has prevailed on the merits of at least some of his claims, either in the trial court or on appeal. Respondents have not prevailed on the merits of any of their claims, since the Court of Appeals held …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"16-18","2":"25, 40","3":"8, 16"}},{"t":"case","label":"Hensley v. Eckerhart","cite":"461 U.S. 424","y":1983,"id":"1982/81-1244","sc":1,"op":4,"sum":"The District Court did not properly consider the relationship between the extent of success and the amount of the attorney's fee award. The extent of a plaintiff's success is a crucial factor in determining the proper amount of an attorney's fee award under § 1988. Where the plaintiff failed to prevail on a claim unrelated to the successful claims, the hours spent on the unsuccessful claim should be excluded in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 46","2":"25, 29, 53"}},{"t":"case","label":"Hewitt v. Helms","cite":"482 U.S. 755","y":1987,"id":"1986/85-1630","sc":1,"op":3,"sum":"Respondent is not a \"prevailing party\" eligible for attorney's fees under § 1988. A plaintiff must receive at least some relief on the merits of his claim before he can be said to \"prevail.\" Respondent obtained neither a damages award, injunction, or declaratory judgment, nor a consent decree, settlement, or other relief without benefit of a formal judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"15, 17, 18","2":"16, 24-25","3":"5, 6, 13, 16"}},{"t":"case","label":"Higher Taste, Inc. v. City of Tacoma","cite":"717 F.3d 712","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/717/712/","op":1,"by":{"0":"34, 40, 46"}},{"t":"case","label":"Higuchi Int’l Corp. v. Autoliv ASP, Inc.","cite":"103 F.4th 400","y":2024,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/103/400/","by":{"0":"31"}},{"t":"case","label":"Independent Fed’n of Flight Attendants v. Zipes","cite":"491 U.S. 754","y":1989,"id":"1988/88-608","sc":1,"op":2,"sum":"District courts may award Title VII attorney's fees against those who are not charged with Title VII violations but intervene to protect their own rights only where the intervention is frivolous, unreasonable, or without foundation. Assessing fees against blameless intervenors is not essential to § 706(k)'s central purpose of providing victims of wrongful discrimination an incentive to file suit. The prospect of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20","1":"15","3":"6"}},{"t":"case","label":"Kansas Jud. Watch v. Stout","cite":"653 F.3d 1230","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/1230/","op":1,"by":{"0":"47"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"575 U.S. 650","y":2015,"id":"2014/12-1497","sc":1,"sum":"The Wartime Suspension of Limitations Act's statute of limitations tolling provision does not apply to claims of civil fraud brought by private parties. The False Claims Act's \"first-to-file bar\" keeps new claims out of court only while related claims are still alive, but not in perpetuity.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Kentucky v. Graham","cite":"473 U.S. 159","y":1985,"id":"1984/84-849","sc":1,"sum":"Section 1988 does not allow attorney's fees to be recovered from a governmental entity when a plaintiff sues governmental employees only in their personal capacities and prevails; accordingly, since this case was necessarily litigated as a personal-capacity and not as an officialcapacity action, it was error to award fees against the Commonwealth.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 19, 20","1":"15, 17, 31","2":"32","3":"6"}},{"t":"case","label":"Landis v. North Am. Co.","cite":"299 U.S. 248","y":1936,"id":"scdb/1936-018","sc":1,"sum":"(1) That to grant the stay until decision of the other case by this Court on appeal, was abuse of discretion. P. 256. (2) The question whether the stay would have been proper under the conditions which existed when it was granted, had it been granted to continue only until decision of the other case by the District Court, is a question which this Court will not decide, because the conditions have changed. P. 258. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Lewis v. Continental Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"sum":"Before 1987, the Bank Holding Company Act of 1956 (BHCA) allowed States to prohibit an out-of-state bank holding company from owning an in-state \"bank,\" which was defined to include an institution that both accepted demand deposits and engaged in the commercial lending business. In 1981, appellee, an Illinois bank holding company, applied to Florida to establish and operate an \"industrial savings bank\" (ISB) in that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"38","3":"17"}},{"t":"case","label":"M Welles & Assocs., Inc. v. Edwell, Inc.","cite":"69 F.4th 723","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/69/723/","by":{"0":"52"}},{"t":"case","label":"Maher v. Gagne","cite":"448 U.S. 122","y":1980,"id":"1979/78-1888","sc":1,"op":2,"ar":2,"sum":"Respondent is a recipient of benefits under Connecticut's federally funded Aid to Families with Dependent Children (AFDC) program. She brought this action in Federal District Court under 42 U. S. C. § 1983, alleging that Connecticut's AFDC regulations denied her credit for substantial portions of her actual work-related expenses, thus reducing the level of her benefits, and that'such regulations violated the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"15","2":"13, 30-31, 40"}},{"t":"case","label":"Mastrio v. Sebelius","cite":"768 F.3d 116","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/768/116/","by":{"0":"48"}},{"t":"case","label":"McQueary v. Conway","cite":"614 F.3d 591","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/614/591/","op":1,"by":{"0":"47, 48","3":"10, 18, 19"}},{"t":"case","label":"Mendoza v. Strickler","cite":"51 F.4th 346","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/51/346/","by":{"0":"28, 30"}},{"t":"case","label":"Mills v. Electric Auto-Lite Co.","cite":"396 U.S. 375","y":1970,"id":"1969/64","sc":1,"ar":1,"sum":"Petitioners, minority shareholders of respondent Electric Auto-Lite Co., brought this action derivatively and on behalf of minority shareholders as a class to set aside a merger of Auto-Lite and the Mergenthaler Linotype Co. (which before the merger owned over half of Auto-Lite's stock). Petitioners charged that the proxy solicitation for the merger by Auto-Lite's management was materially misleading and violated § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"18, 19"}},{"t":"case","label":"Mock v. Garland","cite":"75 F.4th 563","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/75/563/","by":{"0":"25"}},{"t":"case","label":"Mullins v. City of New York","cite":"626 F.3d 47","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/626/47/","by":{"0":"23"}},{"t":"case","label":"National Black Police Ass’n v. District of Columbia","cite":"108 F.3d 346","y":1997,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/108/346/","op":14,"by":{"0":"51"}},{"t":"case","label":"Northern Cheyenne Tribe v. Jackson","cite":"433 F.3d 1083","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/433/1083/","op":1,"by":{"0":"37, 44, 49","3":"18"}},{"t":"case","label":"People Against Police Violence v. City of Pittsburgh","cite":"520 F.3d 226","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/520/226/","op":1,"by":{"0":"31","2":"23","3":"14"}},{"t":"case","label":"Real Truth About Obama, Inc. v. Federal Elec. Comm’n","cite":"575 F.3d 342","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/342/","by":{"0":"10"}},{"t":"case","label":"Rector v. City & Cnty. of Denver","cite":"348 F.3d 935","y":2003,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/348/935/","by":{"0":"28"}},{"t":"case","label":"Rhodes v. Stewart","cite":"488 U.S. 1","y":1988,"id":"1988/88-139","sc":1,"op":2,"sum":"Holding that no fees were available under § 1988 when the judgment afforded no relief to the plaintiff due to mootness.","sumSrc":"opinion","by":{"0":"35"}},{"t":"case","label":"Roberts v. Neace","cite":"65 F.4th 280","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/280/","by":{"0":"38","2":"39"}},{"t":"case","label":"Rogers Grp., Inc. v. City of Fayetteville, Ark.","cite":"683 F.3d 903","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/683/903/","op":1,"by":{"0":"48"}},{"t":"case","label":"Select Milk Producers, Inc. v. Johanns","cite":"400 F.3d 939","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/400/939/","op":1,"sum":"Noting that while the majority characterized the preliminary injunction as providing “permanent” relief, it simply “preserve[d] the status quo” by “restoring the regulatory landscape that existed before the [challenged] Order”.","sumSrc":"brief:0","by":{"0":"25, 35, 38, 40, 47","2":"27"}},{"t":"case","label":"Sinapi v. Rhode Island Bd. of Bar Exam’rs","cite":"910 F.3d 544","y":2018,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/910/544/","op":1,"by":{"0":"47"}},{"t":"case","label":"Singer Mgmt. Consultants, Inc. v. Milgram","cite":"650 F.3d 223","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/650/223/","op":2,"sum":"Noting that “courts use a bewildering variety of formulations of the need for showing some likelihood of success” (quotation marks omitted).","sumSrc":"brief:0","by":{"0":"14, 31-32, 48","3":"18"}},{"t":"case","label":"Smyth ex rel. Smyth v. Rivero","cite":"282 F.3d 268","y":2002,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/282/268/","op":5,"ar":2,"by":{"0":"10, 24","1":"4","2":"9-10, 44"}},{"t":"case","label":"Sole v. Wyner","cite":"551 U.S. 74","y":2007,"id":"2006/06-531","sc":1,"op":17,"ar":22,"sum":"Observing that a plaintiff does not prevail if “at the end of the litigation, her Jackson, J., dissenting initial success is undone and she leaves the courthouse emptyhanded”.","sumSrc":"opinion","by":{"0":"2, 3, 14, 19, 24, 27, 33, 34, 36, 38, 39, 45","1":"27, 29","2":"13, 21-22, 29, 36-39, 41, 49, 52","3":"1, 2, 11, 13, 14, 16, 19"}},{"t":"case","label":"Soon Hing v. Crowley","cite":"113 U.S. 703","y":1885,"id":"scdb/1884-166","sc":1,"sum":"The decision in Barbier v. Connelly, ante, 27 — that a municipal ordinance prohibiting from washing and ironing in public laundries and wash-houses within defined territorial limits, from ten o’clock at night to six in the morning, is a police regulation within the competency of a municipality possessed of ordinary powers — affirmed.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Stanley v. University of S. Cal.","cite":"13 F.3d 1313","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/13/1313/","by":{"0":"23"}},{"t":"case","label":"Starbucks Corp. v. McKinney, __ U.S. __","cite":"2024 WL 2964141","y":2024,"court":"June 13","by":{"0":"24, 34"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"396 F. Supp. 3d 653","y":2019,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/396/653/","op":1,"by":{"0":"5, 6","2":"8","3":"25"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"2017 WL 963234","y":2017,"court":"W.D. Va. Mar. 13","by":{"0":"5, 29"}},{"t":"case","label":"Supreme Ct. of Va. v. Consumers Union of the U.S., Inc.","cite":"446 U.S. 719","y":1980,"id":"1979/79-198","sc":1,"op":4,"sum":"The Court held that the Supreme Court of Virginia was immune to suits in its legislative capacity, just as any other legislative body would be. However, the Supreme Court of Virginia has the power to enforce the Code, and this suit was brought against it in its enforcement capacity.","sumSrc":"Oyez","by":{"0":"20","1":"15"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"0":"18","1":"13, 23"}},{"t":"case","label":"Tennessee State Conf. of NAACP v. Hargett","cite":"53 F.4th 406","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/53/406/","op":1,"by":{"0":"35, 38","3":"14"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"sum":"From the allegations of the complaint, it appears that petitioners were acting in a field where legislators traditionally have power to act; and 8 U. S. C. §§ 43 and 47 (3) do not create civil liability for such conduct.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Texas State Teachers Ass’n v. Garland Indep. Sch. Dist.","cite":"489 U.S. 782","y":1989,"id":"1988/87-1759","sc":1,"op":7,"sum":"Petitioners, state and local teachers' associations and several of their members and employees, brought suit in the District Court under 42 U. S. C. § 1983, alleging that respondent school district's policy of prohibiting communications by or with teachers during the schoolday concerning employee organizations violated their First and Fourteenth Amendment rights in various particular respects. The District Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 22, 33, 46","1":"20-22","2":"22-23, 29, 33, 40-41, 50","3":"5, 6, 15"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Tully v. Okeson","cite":"78 F.4th 377","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/78/377/","by":{"0":"26"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"op":1,"sum":"Title 8 U. S. C. §1324(a)(1)(A)(iv)—which criminalizes “encouraging or inducing” illegal immigration—forbids only the purposeful solicitation and facilitation of specific acts known to violate federal law and is not unconstitutionally overbroad.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18"}},{"t":"case","label":"University of Tex. v. Camenisch","cite":"451 U.S. 390","y":1981,"id":"1980/80-317","sc":1,"op":3,"sum":"The question whether a preliminary injunction should have been issued is moot because the terms of the injunction have been fully and irrevocably carried out, but, as the Court of Appeals correctly noted, the question whether the University must pay for the interpreter remains for trial on the merits.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 23, 24, 26, 34","1":"11, 25-27, 31","2":"24","3":"12, 20"}},{"t":"case","label":"Uzuegbunam v. Preczewski","cite":"592 U.S. 279","y":2021,"id":"2020/19-968","sc":1,"sum":"A request for nominal damages satisfies the redressability element necessary for Article III standing where a plaintiff’s claim is based on a completed violation of a legal right.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"52","3":"23"}},{"t":"case","label":"Valero Terrestrial Corp. v. Paige","cite":"211 F.3d 112","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/211/112/","by":{"0":"50"}},{"t":"case","label":"West Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Winter v. Natural Resources Defense Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"op":7,"ar":4,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"0":"10, 25","2":"5, 33"}},{"t":"case","label":"Withrow v. Larkin","cite":"421 U.S. 35","y":1975,"id":"1974/73-1573","sc":1,"op":3,"sum":"Wisconsin statutes prohibit various acts of professional misconduct by physicians and empower a State Examining Board to warn and reprimand physicians, to temporarily suspend licenses, and to institute criminal action or action to revoke a license. When the Board notified appellee licensed physician that a closed investigative hearing, which appellee and his attorney could attend, would be held to determine whether …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Young v. City of Chicago","cite":"202 F.3d 1000","y":2000,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/202/1000/","op":1,"by":{"0":"44"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(a)(4)(E)(ii)(II)"],"stext":{"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","paras":[[0,"(a) Each agency shall make available to the public information as follows:"],[0,"(1) Each agency shall separately state and currently publish in the Federal Register for the guidance of the public—"],[1,"(A) descriptions of its central and field organization and the established places at which, the employees (and in the case of a uniformed service, the members) from whom, and the methods whereby, the public may obtain information, make submittals or requests, or obtain decisions;"],[1,"(B) statements of the general course and method by which its functions are channeled and determined, including the nature and requirements of all formal and informal procedures available;"],[1,"(C) rules of procedure, descriptions of forms available or the places at which forms may be obtained, and instructions as to the scope and contents of all papers, reports, or examinations;"],[1,"(D) substantive rules of general applicability adopted as authorized by law, and statements of general policy or interpretations of general applicability formulated and adopted by the agency; and"],[1,"(E) each amendment, revision, or repeal of the foregoing."],[0,"Except to the extent that a person has actual and timely notice of the terms thereof, a person may not in any manner be required to resort to, or be adversely affected by, a matter required to be published in the Federal Register and not so published. For the purpose of this paragraph, matter reasonably available to the class of persons affected thereby is deemed published in the Federal Register when incorporated by reference therein with the approval of the Director of the Federal Register."],[0,"(2) Each agency, in accordance with published rules, shall make available for public inspection in an electronic format—"],[1,"(A) final opinions, including concurring and dissenting opinions, as well as orders, made in the adjudication of cases;"],[1,"(B) those statements of policy and interpretations which have been adopted by the agency and are not published in the Federal Register;"],[1,"(C) administrative staff manuals and instructions to staff that affect a member of the public;"],[1,"(D) copies of all records, regardless of form or format—"],[2,"(i) that have been released to any person under paragraph (3); and"],[2,"(ii)(I) that because of the nature of their subject matter, the agency determines have become or are likely to become the subject of subsequent requests for substantially the same records; or"],[2,"(II) that have been requested 3 or more times; and"],[1,"(E) a general index of the records referred to under subparagraph (D);"],[0,"unless the materials are promptly published and copies offered for sale. For records created on or after November 1, 1996, within one year after such date, each agency shall make such records available, including by computer telecommunications or, if computer telecommunications means have not been established by the agency, by other electronic means. To the extent required to prevent a clearly unwarranted invasion of personal privacy, an agency may delete identifying details when it makes available or publishes an opinion, statement of policy, interpretation, staff manual, instruction, or copies of records referred to in subparagraph (D). However, in each case the justification for the deletion shall be explained fully in writing, and the extent of such deletion shall be indicated on the portion of the record which is made available or published, unless including that indication would harm an interest protected by the exemption in subsection (b) under which the deletion is made. If technically feasible, the extent of the deletion shall be indicated at the place in the record where the deletion was made. Each agency shall also maintain and make available for public inspection in an electronic format current indexes providing identifying information for the public as to any matter issued, adopted, or promulgated after July 4, 1967, and required by this paragraph to be made available or published. Each agency shall promptly publish, quarterly or more frequently, and distribute (by sale or otherwise) copies of each index or supplements thereto unless it determines by order published in the Federal Register that the publication would be unnecessary and impracticable, in which case the agency shall nonetheless provide copies of such index on request at a cost not to exceed the direct cost of duplication. Each agency shall make the index referred to in subparagraph (E) available by computer telecommunications by December 31, 1999. A final order, opinion, statement of policy, interpretation, or staff manual or instruction that affects a member of the public may be relied on, used, or cited as precedent by an agency against a party other than an agency only if—"],[1,"(i) it has been indexed and either made available or published as provided by this paragraph; or"],[1,"(ii) the party has actual and timely notice of the terms thereof."],[0,"(3)(A) Except with respect to the records made available under paragraphs (1) and (2) of this subsection, and except as provided in subparagraph (E), each agency, upon any request for records which (i) reasonably describes such records and (ii) is made in accordance with published rules stating the time, place, fees (if any), and procedures to be followed, shall make the records promptly available to any person."],[0,"(B) In making any record available to a person under this paragraph, an agency shall provide the record in any form or format requested by the person if the record is readily reproducible by the agency in that form or format. Each agency shall make reasonable efforts to maintain its records in forms or formats that are reproducible for purposes of this section."],[0,"(C) In responding under this paragraph to a request for records, an agency shall make reasonable efforts to search for the records in electronic form or format, except when such efforts would significantly interfere with the operation of the agency's automated information system."],[0,"(D) For purposes of this paragraph, the term \"search\" means to review, manually or by automated means, agency records for the purpose of locating those records which are responsive to a request."],[0,"(E) An agency, or part of an agency, that is an element of the intelligence community (as that term is defined in section 3(4) of the National Security Act of 1947 (50 U.S.C. 401a(4))) 1 shall not make any record available under this paragraph to—"],[1,"(i) any government entity, other than a State, territory, commonwealth, or district of the United States, or any subdivision thereof; or"],[1,"(ii) a representative of a government entity described in clause (i)."],[0,"(4)(A)(i) In order to carry out the provisions of this section, each agency shall promulgate regulations, pursuant to notice and receipt of public comment, specifying the schedule of fees applicable to the processing of requests under this section and establishing procedures and guidelines for determining when such fees should be waived or reduced. Such schedule shall conform to the guidelines which shall be promulgated, pursuant to notice and receipt of public comment, by the Director of the Office of Management and Budget and which shall provide for a uniform schedule of fees for all agencies."],[0,"(ii) Such agency regulations shall provide that—"],[1,"(I) fees shall be limited to reasonable standard charges for document search, duplication, and review, when records are requested for commercial use;"],[1,"(II) fees shall be limited to reasonable standard charges for document duplication when records are not sought for commercial use and the request is made by an educational or noncommercial scientific institution, whose purpose is scholarly or scientific research; or a representative of the news media; and"],[1,"(III) for any request not described in (I) or (II), fees shall be limited to reasonable standard charges for document search and duplication."],[0,"In this clause, the term \"a representative of the news media\" means any person or entity that gathers information of potential interest to a segment of the public, uses its editorial skills to turn the raw materials into a distinct work, and distributes that work to an audience. In this clause, the term \"news\" means information that is about current events or that would be of current interest to the public. Examples of news-media entities are television or radio stations broadcasting to the public at large and publishers of periodicals (but only if such entities qualify as disseminators of \"news\") who make their products available for purchase by or subscription by or free distribution to the general public. These examples are not all-inclusive. Moreover, as methods of news delivery evolve (for example, the adoption of the electronic dissemination of newspapers through telecommunications services), such alternative media shall be considered to be news-media entities. A freelance journalist shall be regarded as working for a news-media entity if the journalist can demonstrate a solid basis for expecting publication through that entity, whether or not the journalist is actually employed by the entity. A publication contract would present a solid basis for such an expectation; the Government may also consider the past publication record of the requester in making such a determination."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§552. Public information; agency rules, opinions, orders, records, and proceedings","tname":"Government Organization and Employees","by":{"0":"54","1":"32, 32"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(b)","(d)(1)(A)","(d)(2)(H)"],"stext":{"head":"§2412. Costs and fees","paras":[[0,"(a)(1) Except as otherwise specifically provided by statute, a judgment for costs, as enumerated in section 1920 of this title, but not including the fees and expenses of attorneys, may be awarded to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. A judgment for costs when taxed against the United States shall, in an amount established by statute, court rule, or order, be limited to reimbursing in whole or in part the prevailing party for the costs incurred by such party in the litigation."],[0,"(2) A judgment for costs, when awarded in favor of the United States in an action brought by the United States, may include an amount equal to the filing fee prescribed under section 1914(a) of this title. The preceding sentence shall not be construed as requiring the United States to pay any filing fee."],[0,"(b) Unless expressly prohibited by statute, a court may award reasonable fees and expenses of attorneys, in addition to the costs which may be awarded pursuant to subsection (a), to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. The United States shall be liable for such fees and expenses to the same extent that any other party would be liable under the common law or under the terms of any statute which specifically provides for such an award."],[0,"(c)(1) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for costs pursuant to subsection (a) shall be paid as provided in sections 2414 and 2517 of this title and shall be in addition to any relief provided in the judgment."],[0,"(2) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for fees and expenses of attorneys pursuant to subsection (b) shall be paid as provided in sections 2414 and 2517 of this title, except that if the basis for the award is a finding that the United States acted in bad faith, then the award shall be paid by any agency found to have acted in bad faith and shall be in addition to any relief provided in the judgment."],[0,"(d)(1)(A) Except as otherwise specifically provided by statute, a court shall award to a prevailing party other than the United States fees and other expenses, in addition to any costs awarded pursuant to subsection (a), incurred by that party in any civil action (other than cases sounding in tort), including proceedings for judicial review of agency action, brought by or against the United States in any court having jurisdiction of that action, unless the court finds that the position of the United States was substantially justified or that special circumstances make an award unjust."],[0,"(B) A party seeking an award of fees and other expenses shall, within thirty days of final judgment in the action, submit to the court an application for fees and other expenses which shows that the party is a prevailing party and is eligible to receive an award under this subsection, and the amount sought, including an itemized statement from any attorney or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the United States was not substantially justified. Whether or not the position of the United States was substantially justified shall be determined on the basis of the record (including the record with respect to the action or failure to act by the agency upon which the civil action is based) which is made in the civil action for which fees and other expenses are sought."],[0,"(C) The court, in its discretion, may reduce the amount to be awarded pursuant to this subsection, or deny an award, to the extent that the prevailing party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy."],[0,"(D) If, in a civil action brought by the United States or a proceeding for judicial review of an adversary adjudication described in section 504(a)(4) of title 5, the demand by the United States is substantially in excess of the judgment finally obtained by the United States and is unreasonable when compared with such judgment, under the facts and circumstances of the case, the court shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this subparagraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(2) For the purposes of this subsection—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the court to be necessary for the preparation of the party's case, and reasonable attorney fees (The amount of fees awarded under this subsection shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the United States; and (ii) attorney fees shall not be awarded in excess of $125 per hour unless the court determines that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means (i) an individual whose net worth did not exceed $2,000,000 at the time the civil action was filed, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the civil action was filed, and which had not more than 500 employees at the time the civil action was filed; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (d)(1)(D), a small entity as defined in section 601 of title 5;"],[1,"(C) \"United States\" includes any agency and any official of the United States acting in his or her official capacity;"],[1,"(D) \"position of the United States\" means, in addition to the position taken by the United States in the civil action, the action or failure to act by the agency upon which the civil action is based; except that fees and expenses may not be awarded to a party for any portion of the litigation in which the party has unreasonably protracted the proceedings;"],[1,"(E) \"civil action brought by or against the United States\" includes an appeal by a party, other than the United States, from a decision of a contracting officer rendered pursuant to a disputes clause in a contract with the Government or pursuant to chapter 71 of title 41;"],[1,"(F) \"court\" includes the United States Court of Federal Claims and the United States Court of Appeals for Veterans Claims;"],[1,"(G) \"final judgment\" means a judgment that is final and not appealable, and includes an order of settlement;"],[1,"(H) \"prevailing party\", in the case of eminent domain proceedings, means a party who obtains a final judgment (other than by settlement), exclusive of interest, the amount of which is at least as close to the highest valuation of the property involved that is attested to at trial on behalf of the property owner as it is to the highest valuation of the property involved that is attested to at trial on behalf of the Government; and"],[1,"(I) \"demand\" means the express demand of the United States which led to the adversary adjudication, but shall not include a recitation of the maximum statutory penalty (i) in the complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(3) In awarding fees and other expenses under this subsection to a prevailing party in any action for judicial review of an adversary adjudication, as defined in subsection (b)(1)(C) of section 504 of title 5, or an adversary adjudication subject to chapter 71 of title 41, the court shall include in that award fees and other expenses to the same extent authorized in subsection (a) of such section, unless the court finds that during such adversary adjudication the position of the United States was substantially justified, or that special circumstances make an award unjust."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2412?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2412. Costs and fees","tname":"Judiciary and Judicial Procedure","by":{"0":"16","1":"1, 1","2":"19"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"52","1":"1, 4","2":"3"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","subs":["(b)"],"stext":{"head":"§1988. Proceedings in vindication of civil rights","paras":[[0,"(a) Applicability of statutory and common law"],[0,"The jurisdiction in civil and criminal matters conferred on the district courts by the provisions of titles 13, 24, and 70 of the Revised Statutes for the protection of all persons in the United States in their civil rights, and for their vindication, shall be exercised and enforced in conformity with the laws of the United States, so far as such laws are suitable to carry the same into effect; but in all cases where they are not adapted to the object, or are deficient in the provisions necessary to furnish suitable remedies and punish offenses against law, the common law, as modified and changed by the constitution and statutes of the State wherein the court having jurisdiction of such civil or criminal cause is held, so far as the same is not inconsistent with the Constitution and laws of the United States, shall be extended to and govern the said courts in the trial and disposition of the cause, and, if it is of a criminal nature, in the infliction of punishment on the party found guilty."],[0,"(b) Attorney's fees"],[0,"In any action or proceeding to enforce a provision of sections 1981, 1981a, 1982, 1983, 1985, and 1986 of this title, title IX of Public Law 92–318 [20 U.S.C. 1681 et seq.], the Religious Freedom Restoration Act of 1993 [42 U.S.C. 2000bb et seq.], the Religious Land Use and Institutionalized Persons Act of 2000 [42 U.S.C. 2000cc et seq.], title VI of the Civil Rights Act of 1964 [42 U.S.C. 2000d et seq.], or section 12361 of title 34, the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee as part of the costs, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity such officer shall not be held liable for any costs, including attorney's fees, unless such action was clearly in excess of such officer's jurisdiction."],[0,"(c) Expert fees"],[0,"In awarding an attorney's fee under subsection (b) in any action or proceeding to enforce a provision of section 1981 or 1981a of this title, the court, in its discretion, may include expert fees as part of the attorney's fee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1988?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":8,"head":"§1988. Proceedings in vindication of civil rights","tname":"The Public Health and Welfare","by":{"0":"1, 2, 18","1":"1, 8, 18, 1","2":"1-3, 11-12, 14-15, 17-19, 21-23, 30, 37, 40-43, 46-47, 53","3":"5"}},{"t":"usc","label":"16 U.S.C. § 3117","url":"https://www.law.cornell.edu/uscode/text/16/3117","by":{"0":"16"}},{"t":"usc","label":"5 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/5/504","subs":["(a)(2)"],"stext":{"head":"§504. Costs and fees of parties","paras":[[0,"(a)(1) An agency that conducts an adversary adjudication shall award, to a prevailing party other than the United States, fees and other expenses incurred by that party in connection with that proceeding, unless the adjudicative officer of the agency finds that the position of the agency was substantially justified or that special circumstances make an award unjust. Whether or not the position of the agency was substantially justified shall be determined on the basis of the administrative record, as a whole, which is made in the adversary adjudication for which fees and other expenses are sought."],[0,"(2) A party seeking an award of fees and other expenses shall, within thirty days of a final disposition in the adversary adjudication, submit to the agency an application which shows that the party is a prevailing party and is eligible to receive an award under this section, and the amount sought, including an itemized statement from any attorney, agent, or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the agency was not substantially justified. When the United States appeals the underlying merits of an adversary adjudication, no decision on an application for fees and other expenses in connection with that adversary adjudication shall be made under this section until a final and unreviewable decision is rendered by the court on the appeal or until the underlying merits of the case have been finally determined pursuant to the appeal."],[0,"(3) The adjudicative officer of the agency may reduce the amount to be awarded, or deny an award, to the extent that the party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy. The decision of the adjudicative officer of the agency under this section shall be made a part of the record containing the final decision of the agency and shall include written findings and conclusions and the reason or basis therefor. The decision of the agency on the application for fees and other expenses shall be the final administrative decision under this section."],[0,"(4) If, in an adversary adjudication arising from an agency action to enforce a party's compliance with a statutory or regulatory requirement, the demand by the agency is substantially in excess of the decision of the adjudicative officer and is unreasonable when compared with such decision, under the facts and circumstances of the case, the adjudicative officer shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this paragraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(b)(1) For the purposes of this section—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the agency to be necessary for the preparation of the party's case, and reasonable attorney or agent fees (The amount of fees awarded under this section shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the agency involved, and (ii) attorney or agent fees shall not be awarded in excess of $125 per hour unless the agency determines by regulation that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys or agents for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means a party, as defined in section 551(3) of this title, who is (i) an individual whose net worth did not exceed $2,000,000 at the time the adversary adjudication was initiated, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the adversary adjudication was initiated, and which had not more than 500 employees at the time the adversary adjudication was initiated; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (a)(4), a small entity as defined in section 601;"],[1,"(C) \"adversary adjudication\" means (i) an adjudication under section 554 of this title in which the position of the United States is represented by counsel or otherwise, but excludes an adjudication for the purpose of establishing or fixing a rate or for the purpose of granting or renewing a license, (ii) any appeal of a decision made pursuant to section 7103 of title 41 before an agency board of contract appeals as provided in section 7105 of title 41, (iii) any hearing conducted under chapter 38 of title 31, and (iv) the Religious Freedom Restoration Act of 1993;"],[1,"(D) \"adjudicative officer\" means the deciding official, without regard to whether the official is designated as an administrative law judge, a hearing officer or examiner, or otherwise, who presided at the adversary adjudication;"],[1,"(E) \"position of the agency\" means, in addition to the position taken by the agency in the adversary adjudication, the action or failure to act by the agency upon which the adversary adjudication is based; except that fees and other expenses may not be awarded to a party for any portion of the adversary adjudication in which the party has unreasonably protracted the proceedings; and"],[1,"(F) \"demand\" means the express demand of the agency which led to the adversary adjudication, but does not include a recitation by the agency of the maximum statutory penalty (i) in the administrative complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(2) Except as otherwise provided in paragraph (1), the definitions provided in section 551 of this title apply to this section."],[0,"(c)(1) After consultation with the Chairman of the Administrative Conference of the United States, each agency shall by rule establish uniform procedures for the submission and consideration of applications for an award of fees and other expenses. If a court reviews the underlying decision of the adversary adjudication, an award for fees and other expenses may be made only pursuant to section 2412(d)(3) of title 28."],[0,"(2) If a party other than the United States is dissatisfied with a determination of fees and other expenses made under subsection (a), that party may, within 30 days after the determination is made, appeal the determination to the court of the United States having jurisdiction to review the merits of the underlying decision of the agency adversary adjudication. The court's determination on any appeal heard under this paragraph shall be based solely on the factual record made before the agency. The court may modify the determination of fees and other expenses only if the court finds that the failure to make an award of fees and other expenses, or the calculation of the amount of the award, was unsupported by substantial evidence."],[0,"(d) Fees and other expenses awarded under this subsection shall be paid by any agency over which the party prevails from any funds made available to the agency by appropriation or otherwise."],[0,"(e)(1) Not later than March 31 of the first fiscal year beginning after the date of enactment of the John D. Dingell, Jr. Conservation, Management, and Recreation Act, and every fiscal year thereafter, the Chairman of the Administrative Conference of the United States, after consultation with the Chief Counsel for Advocacy of the Small Business Administration, shall submit to Congress and make publicly available online a report on the amount of fees and other expenses awarded during the preceding fiscal year under this section."],[0,"(2) Each report under paragraph (1) shall describe the number, nature, and amount of the awards, the claims involved in the controversy, and any other relevant information that may aid Congress in evaluating the scope and impact of such awards."],[0,"(3)(A) Each report under paragraph (1) shall account for all payments of fees and other expenses awarded under this section that are made pursuant to a settlement agreement, regardless of whether the settlement agreement is sealed or otherwise subject to a nondisclosure provision."],[0,"(B) The disclosure of fees and other expenses required under subparagraph (A) shall not affect any other information that is subject to a nondisclosure provision in a settlement agreement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/504?type=usc&year=mostrecent&link-type=html"},"head":"§504. Costs and fees of parties","tname":"Government Organization and Employees","by":{"0":"16","2":"19"}},{"t":"usc","label":"42 U.S.C. § 3612","url":"https://www.law.cornell.edu/uscode/text/42/3612","by":{"0":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","by":{"0":"26, 52","2":"48","3":"23"}},{"t":"case","label":"Astrue v. Ratliff","cite":"560 U.S. 586","y":2010,"id":"2009/08-1322","sc":1,"sum":"The Court determined that an award of attorney’s fees under the Equal Access to Justice Act can be used to offset the prevailing party’s preexisting debt to the government.","sumSrc":"Oyez","by":{"1":"12","3":"3"}},{"t":"case","label":"(III) Cases—Continued: Benisek v. Lamone","cite":"585 U.S. 155","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/155/","sc":1,"by":{"1":"25"}},{"t":"case","label":"Crawford Fitting Co. v. J.T. Gibbons, Inc.","cite":"482 U.S. 437","y":1987,"id":"1986/86-322","sc":1,"op":1,"sum":"When a prevailing party seeks reimbursement for fees paid to its expert witnesses, a federal court is bound by the limits of § 1821(b), absent contract or explicit statutory authority to the contrary. There is no merit to petitioners' contentions that, since § 1920 lists expenses which a court \"may\" tax as costs, it only authorizes taxation of such items and does not preclude taxation for other items or amounts in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"CRST Van Expedited, Inc. v. EEOC","cite":"578 U.S. 419","y":2016,"id":"2015/14-1375","sc":1,"op":3,"sum":"The Court determined that a defendant may be a “prevailing party” for the purpose of the award of fees even without a ruling on the merits.","sumSrc":"Oyez","by":{"1":"20","2":"21, 41, 53"}},{"t":"case","label":"Edgar v. MITE Corp.","cite":"457 U.S. 624","y":1982,"id":"1981/80-1188","sc":1,"sum":"With regard to the Commerce Clause. The Illinois Act imposes burdens on interstate commerce that are excessive in light of the local interests the Act purports to further. Among the ways a corporation can be covered by the Act is if 10% of the class of equity securities subject to the offer is owned by shareholders located in Illinois.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Fourco Glass Co. v. Transmirra Prods. Corp.","cite":"353 U.S. 222","y":1957,"id":"1956/310","sc":1,"sum":"1. Venue in patent infringement actions is governed exclusively by 28 U. S. C. § 1400 (b), which provides that any such action may be brought \"in the judicial district where the defendant resides, or where the defendant has committed acts of infringement and has a regular and established place of business\"; and 28 U. S. C. § 1391 (c) has no application to such actions. Stonite Products Co. v. Melvin Lloyd Co., 315 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Frew ex rel. Frew v. Hawkins","cite":"540 U.S. 431","y":2004,"id":"2003/02-628","sc":1,"sum":"The Court held that enforcement of the consent decree does not violate the 11th Amendment.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Kansas v. Colorado","cite":"556 U.S. 98","y":2009,"id":"2008/105-orig","sc":1,"sum":"The Court held that expert witness fees should be the same when brought in front of the Supreme Court and the federal district courts.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"579 U.S. 197","y":2016,"id":"2015/15-375","sc":1,"op":1,"ar":1,"sum":"The Court determined that, when deciding whether to grant attorney’s fees under Section 505 of the Copyright Act, courts should give substantial weight to the objective reasonableness of the losing party’s position, but that determination should not be the controlling factor.","sumSrc":"Oyez","by":{"1":"16","2":"32"}},{"t":"case","label":"Local No. 93, Int’l Ass’n of Firefighters v. City of Cleveland","cite":"478 U.S. 501","y":1986,"id":"1985/84-1999","sc":1,"op":1,"sum":"The Court held that section 706(g) of Title VII does not apply to relief awarded in a consent decree.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Marek v. Chesny","cite":"473 U.S. 1","y":1985,"id":"1984/83-1437","sc":1,"sum":"Petitioners are not liable for the attorney's fees incurred by respondent after petitioners' offer of settlement.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Martin v. Franklin Capital Corp.","cite":"546 U.S. 132","y":2005,"id":"2005/04-1140","sc":1,"sum":"The Court ruled that \"absent unusual circumstances, attorney's fees should not be awarded when the removing party has an objectively reasonable basis for removal.\" The Court admitted that Section 1447 is unclear on when attorney's fees should be added. The Court's reading of the statute detected no strong textual bias for or against awarding fees.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Rufo v. Inmates of Suffolk Cnty. Jail","cite":"502 U.S. 367","y":1992,"id":"1991/90-954","sc":1,"sum":"The Court held that the court does not require a grievous wrong evoked by new and unforeseen change of facts in order to modify a consented decree.","sumSrc":"Oyez","by":{"1":"15","3":"9"}},{"t":"case","label":"Thornburgh v. American Coll. of Obstetricians & Gynecologists","cite":"476 U.S. 747","y":1986,"id":"1985/84-495","sc":1,"sum":"In a 5-to-4 decision, the Court held that the Pennsylvania requirements \"wholly subordinate[d] constitutional privacy interests and concerns with maternal health\" and were attempts to deter women from making their own choices concerning abortion.","sumSrc":"Oyez","by":{"1":"26","2":"36"}},{"t":"case","label":"Trump v. International Refugee Assistance Project","cite":"582 U.S. 571","y":2017,"id":"2017/16-1436","sc":1,"op":1,"sum":"A case in which the Court would have decided whether the respondents' challenges to the temporary suspension of entry of aliens abroad under Section 2(c) of Executive Order No. 13,780 became moot on June 14, 2017, whether Section 2(c)'s temporary suspension of entry violates the Establishment Clause, and whether the global injunction issued by the district court is impermissibly overbroad. On June 26, 2017, the Court granted the government's applications for a stay of the preliminary injunction with respect to Sections 6(a) and (b) of Executive Order.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"2"}},{"t":"law","label":"Pub. L. No. 94-559","url":"https://www.govinfo.gov/link/statute/90/2641","by":{"1":"25"}},{"t":"usc","label":"28 U.S.C. § 382","url":"https://www.law.cornell.edu/uscode/text/28/382","subs":["(1934)"],"by":{"1":"23"}},{"t":"usc","label":"28 U.S.C. § 571","url":"https://www.law.cornell.edu/uscode/text/28/571","subs":["(1946)"],"by":{"1":"23"}},{"t":"usc","label":"28 U.S.C. § 830","url":"https://www.law.cornell.edu/uscode/text/28/830","subs":["(1946)"],"by":{"1":"32"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)"],"by":{"1":"32"}},{"t":"usc","label":"28 U.S.C. § 1920","url":"https://www.law.cornell.edu/uscode/text/28/1920","by":{"1":"24, 24"}},{"t":"usc","label":"28 U.S.C. § 1923","url":"https://www.law.cornell.edu/uscode/text/28/1923","subs":["(a)"],"by":{"1":"1"}},{"t":"usc","label":"42 U.S.C. § 300aa-15","url":"https://www.law.cornell.edu/uscode/text/42/300aa-15","subs":["(e)(1)"],"by":{"1":"32"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(k)"],"by":{"1":"1"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(d)"],"by":{"1":"1"}},{"t":"case","label":"Abbott v. Perez","cite":"585 U.S. 579","y":2018,"id":"2017/17-586","sc":1,"sum":"The Court decided that the district court erred in disregarding the presumption of good faith on the part of the Texas Legislature and improperly reversed the burden of proof in requiring the state to show a lack of discriminatory intent in adopting new districting plans; the Court also held that one of the state house districts at issue was an impermissible racial gerrymander.","sumSrc":"Oyez","by":{"2":"27","3":"11"}},{"t":"case","label":"Agency for International Development v. Alliance for Open Society International, Inc.","cite":"570 U.S. 205","y":2013,"id":"2012/12-10","sc":1,"sum":"The Court held that it was a violation of the First Amendment to withhold funding from non-government organizations if they did not institute an anti-prostitution policy.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Allee v. Medrano","cite":"416 U.S. 802","y":1974,"id":"1973/72-1125","sc":1,"sum":"Appellee union and t he individual appellees, who atteitipted from June 1966 to June 1967 to unionize farmworkers and persuade them to support or join a strike, were subjected to persistent harassment and violence by appellants and other law enforcement officers. In July 1967 a state court issued a temporary injunction against appellees, proscribing picketing on or near property of one of the major employers in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Amawi v. Paxton","cite":"956 F.3d 816","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/956/816/","by":{"2":"46"}},{"t":"case","label":"Arizona v. California","cite":"530 U.S. 392","y":2000,"id":"1999/8_orig","sc":1,"sum":"The Court rejected both grounds for preclusion and remanded the case to a Special Master for a determination on the merits of the outstanding claims for additional water rights associated with disputed Fort Yuma Reservation boundary lands. \"Those claims are the only ones that remain to be decided in Arizona v. California; their resolution will enable the Court to enter a final consolidated decree and bring this case to a close,\" wrote Justice Ginsburg for the Court.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Avery v. Wilson","cite":"20 F. 856","y":1884,"court":"C.C.W.D.N.C.","url":"https://www.courtlistener.com/c/F./20/856/","by":{"2":"20"}},{"t":"case","label":"Baltimore Contractors v. Bodinger","cite":"348 U.S. 176","y":1955,"id":"scdb/1954-020","sc":1,"sum":"In an action for an accounting, a federal district court denied a stay under § 3 of the United States Arbitration Act, pending arbitration. Held.: An appeal to a federal court of appeals could not be taken.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Bearden v. Georgia","cite":"461 U.S. 660","y":1983,"id":"1982/81-6633","sc":1,"op":2,"sum":"A sentencing court cannot properly revoke a defendant's probation for failure to pay a fine and make restitution, absent evidence and findings that he was somehow responsible for the failure or that alternative forms of punishment were inadequate to meet the State's interest in punishment and deterrence, and hence here the trial court erred in automatically revoking petitioner's probation and turning the fine into a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Bell v. Burson","cite":"402 U.S. 535","y":1971,"id":"1970/5586","sc":1,"sum":"Georgia's Motor Vehicle Safety Responsibility Act, which provides that the motor vehicle registration and driver's license of an uninsured motorist involved in an accident shall be suspended unless he posts security for the amount of damages claimed by an aggrieved party and which excludes any consideration of fault or responsibility for the accident at a pre-suspension hearing held violative of procedural due …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Benham v. Willmer","cite":"207 P. 592","y":1922,"url":"https://www.courtlistener.com/c/P./207/592/","by":{"2":"20"}},{"t":"case","label":"Boston Bit Labs, Inc. v. Baker","cite":"11 F.4th 3","y":2021,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/11/3/","by":{"2":"45"}},{"t":"case","label":"Brooks v. Byam","cite":"4 F. Cas. 271","y":1843,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./4/271/","by":{"2":"20"}},{"t":"case","label":"Christiansburg Garment Co. v. EEOC","cite":"434 U.S. 412","y":1978,"id":"1977/76-1383","sc":1,"sum":"Two years after a racial discrimination charge under Title VII of the Civil Rights Act of 1964 had been filed against petitioner company, respondent, the Equal Employment Opportunity Commission (EEOC), notified the complainant that its conciliation efforts had failed and that she had the right to sue the company, which she did not do. Almost two years later, § 14 of the 1972 amendments to Title VII authorized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"City of Riverside v. Rivera","cite":"477 U.S. 561","y":1986,"id":"1985/85-224","sc":1,"sum":"Jr., the Court held, 5-4, that there was no requirement under Civil Rights Attorney's Fees Awards Act of 1976 that attorneys' fees be proportionate to the amount of damages a civil rights plaintiff might recover.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"City of San Antonio, Texas v. Hotels.com, L.P.","cite":"593 U.S. 330","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/330/","sc":1,"by":{"2":"50"}},{"t":"case","label":"Clancy v. Geb","cite":"104 N.W. 746","y":1905,"url":"https://www.courtlistener.com/c/N.W./104/746/","ar":1,"by":{"2":"21","3":"8"}},{"t":"case","label":"Consol. California & V. Min. Co. v. Baker","cite":"131 F. 989","y":1904,"court":"C.C.D. Nev.","url":"https://www.courtlistener.com/c/F./131/989/","by":{"2":"20"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Davis v. PBGC","cite":"571 F.3d 1288","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/571/1288/","by":{"2":"34"}},{"t":"case","label":"Eastburn v. Kirk","cite":"1817 WL 1578","y":1817,"court":"N.Y. Ch.","by":{"2":"20"}},{"t":"case","label":"Erlenbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Freedom from Religion Found., Inc. v. Abbott","cite":"58 F.4th 824","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/58/824/","op":4,"by":{"2":"38"}},{"t":"case","label":"Fusari v. Steinberg","cite":"419 U.S. 379","y":1975,"id":"1974/73-848","sc":1,"sum":"The judgment of a three-judge District Court holding that the Connecticut \"seated interview\" procedures for assessing continuing eligibility for unemployment compensation benefits violated due process is vacated, and the case is remanded for reconsideration in light of intervening changes in Connecticut law. Pp. 385-389. 364 F. Supp. 922, vacated and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Garland v. Cargill","cite":"602 U.S. 406","y":2024,"id":"2023/22-976","sc":1,"sum":"The Bureau of Alcohol, Tobacco, Firearms and Explosives exceeded its statutory authority by issuing a Rule that classifies a bump stock as a “machinegun” under 26 U. S. C. §5845(b).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15"}},{"t":"case","label":"Hawse v. Page","cite":"7 F.4th 685","y":2021,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/7/685/","op":4,"by":{"2":"45"}},{"t":"case","label":"Initiative & Referendum Inst. v. U.S. Postal Serv.","cite":"794 F.3d 21","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/794/21/","by":{"2":"39"}},{"t":"case","label":"Kansas Jud. Rev. v. Stout","cite":"562 F.3d 1240","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/562/1240/","by":{"2":"24"}},{"t":"case","label":"Kremens v. Bartley","cite":"431 U.S. 119","y":1977,"id":"1976/75-1064","sc":1,"sum":"Appellees, five mentally ill individuals who were between 15 and 18 years old at the time the complaint was filed, were the named plaintiffs m an action challenging the constitutionality of a 1966 Pennsylvania statute governing the voluntary admission and voluntary commitment to state mental health institutions of persons aged 18 or younger. Appellees sought to vindicate their constitutional rights and to represent …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Lefemine v. Wideman","cite":"568 U.S. 1","y":2012,"id":"2012/12-168","sc":1,"op":4,"ar":2,"sum":"The Court held that the \"prevailing party\" was entitled to award of attorney fees under the Civil Rights Attorney Fees Act.","sumSrc":"Oyez","by":{"2":"22-23, 27, 38","3":"7"}},{"t":"case","label":"Lighthouse Fellowship Church v. Northam","cite":"20 F.4th 157","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/20/157/","by":{"2":"45"}},{"t":"case","label":"McLaughlin by McLaughlin v. Bos. Sch. Comm.","cite":"938 F. Supp. 1001","y":1996,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp./938/1001/","by":{"2":"23"}},{"t":"case","label":"Memphis Cmty. Sch. Dist. v. Stachura","cite":"477 U.S. 299","y":1986,"id":"1985/85-410","sc":1,"sum":"Damages based on the abstract \"value\" or \"importance\" of constitutional rights are not a permissible element of compensatory damages in § 1983 cases.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"2":"36"}},{"t":"case","label":"Muniz v. Hoffman","cite":"422 U.S. 454","y":1975,"id":"1974/73-1924","sc":1,"sum":"After their request for a jury trial was denied, petitioners, a labor union officer and the union, were adjudged guilty of criminal contempt for violating temporary injunctions issued by the District Court pursuant to § 10 (1) of the National Labor Relations Act (NLRA) against picketing of an employer pending the National Labor Relations Board's final disposition of the employer's unfair labor practice charge …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"N.Y. State Rifle & Pistol Ass’n, Inc. v. City of New York","cite":"590 U.S. 336","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/336/","sc":1,"by":{"2":"4, 43, 45, 48"}},{"t":"case","label":"Newton v. Consol. Gas Co. of New York","cite":"265 U.S. 78","y":1924,"id":"scdb/1923-135","sc":1,"sum":"1. Where a New York Commission, made a defendant in the District Court, was later abolished by c. 134, New York Laws 1921, held, that its joinder, or exclusion by summons and severance, was not necessary to sustain an appeal by its codefendants from an order taxing costs.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Pasadena City Bd. of Ed. v. Spangler","cite":"427 U.S. 424","y":1976,"id":"1975/75-164","sc":1,"sum":"In 1968, respondents, Pasadena, Cal., high school students and their parents, brought a purported class action against various school officials seeking injunctive relief from allegedly unconstitutional segregation of the public schools in Pasadena. The United States intervened as a party plaintiff pursuant to § 902 of the Civil Rights Act of 1964, which provides that upon intervention \"the United States shall be …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Pennsylvania v. Del. Valley Citizens’ Council for Clean Air","cite":"478 U.S. 546","y":1986,"url":"https://supreme.justia.com/cases/federal/us/478/546/","sc":1,"op":1,"by":{"2":"4"}},{"t":"case","label":"Pennsylvania v. Wheeling & Belmont Bridge Co.","cite":"59 U.S. 460","y":1855,"id":"scdb/1855-070","sc":1,"sum":"This court has power, in a case of original jurisdiction, to award costs against either of the parties.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Perdue v. Kenny A. ex rel. Winn","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"sum":"The Court held that reasonable attorneys' fees awarded under a federal fee-shifting statute can be enhanced based on the quality of the attorney's performance and results obtained in exceptional circumstances.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Planned Parenthood Ass’n of Utah v. Herbert","cite":"839 F.3d 1301","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/1301/","op":1,"by":{"2":"34"}},{"t":"case","label":"Pleasant View Baptist Church v. Beshear","cite":"838 F. App’x 936","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/838/936/","by":{"2":"45"}},{"t":"case","label":"Pulliam v. Allen","cite":"466 U.S. 522","y":1984,"id":"1983/82-1432","sc":1,"sum":"The Court held that the precedent set by British common law relied on the issuance of writs, rather than the imposition of judicial immunity, to protect judicial independence. The United States never had a doctrine of judicial immunity from prospective relief, and there was no evidence that the lack of that protection created a chilling effect on judicial independence.","sumSrc":"Oyez","by":{"2":"46-47"}},{"t":"case","label":"Resurrection Sch. v. Hertel","cite":"35 F.4th 524","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/35/524/","by":{"2":"45"}},{"t":"case","label":"Roberts v. Neace","cite":"958 F.3d 409","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/958/409/","by":{"2":"24"}},{"t":"case","label":"Roman Catholic Diocese of Brooklyn v. Cuomo","cite":"592 U.S. 14","y":2020,"id":"2020/20a87","sc":1,"sum":"Respondent is enjoined from enforcing Executive Order 202.68’s 10- and 25-person occupancy limits on Applicant pending disposition of the appeal in the United States Court of Appeals for the Second Circuit and disposition of the petition for a writ of certiorari, if such writ is timely sought.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"45","3":"22"}},{"t":"case","label":"S. Bay United Pentecostal Church v. Newsom","cite":"141 S. Ct. 716","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/716/","sc":1,"by":{"2":"44","3":"22"}},{"t":"case","label":"Schenck v. Pro-Choice Network of West New York","cite":"519 U.S. 357","y":1997,"id":"1996/95-1065","sc":1,"sum":"The Court held that while the \"fixed buffer zones\" were constitutional, the \"floating buffer zones\" were not.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Shalala v. Schaefer","cite":"509 U.S. 292","y":1993,"id":"1992/92-311","sc":1,"sum":"In 1986, respondent Schaefer filed a claim for Social Security disability benefits, which was denied by petitioner Secretary at the administrative level. Schaefer sought judicial review and, on April 4,1989, the District Court reversed the administrative denial of benefits and remanded the case to the Secretary pursuant to the fourth sentence of 42 U. S. C. § 405(g). Schaefer was awarded benefits on remand and, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31-32","3":"7"}},{"t":"case","label":"Starbucks Corp. v. McKinney","cite":"144 S. Ct. 1570","y":2024,"id":"2023/23-367","sc":1,"sum":"When considering the National Labor Relations Board’s request for a preliminary injunction under §10( j) of the National Labor Relations Act, district courts must apply the traditional four factors articulated in Winter v. Natural Resources Defense Council, Inc., 555 U. S. 7 (2008).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"33-35","3":"12"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"77 F.4th 200","y":2023,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/77/200/","op":7,"by":{"2":"10-11, 17, 25, 29, 31, 33, 37, 39-40, 43-44, 47, 51-53"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"37 F.4th 977","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/37/977/","op":1,"by":{"2":"10"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"2021 WL 2292807","y":2021,"court":"W.D. Va. June 4","op":1,"by":{"2":"9"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"355 F. Supp. 3d 514","y":2018,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/355/514/","op":2,"by":{"2":"51"}},{"t":"case","label":"Stinnie v. Holcomb","cite":"734 F. App’x 858","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/734/858/","by":{"2":"5"}},{"t":"case","label":"Sys. Fed’n No. 91 v. Wright","cite":"364 U.S. 642","y":1961,"id":"1960/48","sc":1,"sum":"It erred in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"38"}},{"t":"case","label":"Van Tieghem v. Sushenka","cite":"254 Ill. App. 409","y":1929,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/Ill.%20App./254/409/","by":{"2":"20"}},{"t":"case","label":"Veasey v. Wilkins","cite":"158 F. Supp. 3d 466","y":2016,"court":"E.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/158/466/","by":{"2":"24"}},{"t":"case","label":"Williams v. Illinois","cite":"399 U.S. 235","y":1970,"id":"1969/1089","sc":1,"sum":"The Court held that the Equal Protection Clause of the Fourteenth Amendment violated when an impoverished defendant is imprisoned to satisfy payment of a fine and court costs.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Williams v. Wallace","cite":"240 F. Supp. 100","y":1965,"court":"M.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./240/100/","by":{"2":"23"}},{"t":"usc","label":"15 U.S.C. § 6104","url":"https://www.law.cornell.edu/uscode/text/15/6104","subs":["(d)"],"stext":{"head":"§6104. Actions by private persons","paras":[[0,"(a) In general"],[0,"Any person adversely affected by any pattern or practice of telemarketing which violates any rule of the Commission under section 6102 of this title, or an authorized person acting on such person's behalf, may, within 3 years after discovery of the violation, bring a civil action in an appropriate district court of the United States against a person who has engaged or is engaging in such pattern or practice of telemarketing if the amount in controversy exceeds the sum or value of $50,000 in actual damages for each person adversely affected by such telemarketing. Such an action may be brought to enjoin such telemarketing, to enforce compliance with any rule of the Commission under section 6102 of this title, to obtain damages, or to obtain such further and other relief as the court may deem appropriate."],[0,"(b) Notice"],[0,"The plaintiff shall serve prior written notice of the action upon the Commission and provide the Commission with a copy of its complaint, except in any case where such prior notice is not feasible, in which case the person shall serve such notice immediately upon instituting such action. The Commission shall have the right (A) to intervene in the action, (B) upon so intervening, to be heard on all matters arising therein, and (C) to file petitions for appeal."],[0,"(c) Action by Commission or the Bureau of Consumer Financial Protection"],[0,"Whenever a civil action has been instituted by or on behalf of the Commission or the Bureau of Consumer Financial Protection for violation of any rule prescribed under section 6102 of this title, no person may, during the pendency of such action instituted by or on behalf of the Commission or the Bureau of Consumer Financial Protection, institute a civil action against any defendant named in the complaint in such action for violation of any rule as alleged in such complaint."],[0,"(d) Cost and fees"],[0,"The court, in issuing any final order in any action brought under subsection (a), may award costs of suit and reasonable fees for attorneys and expert witnesses to the prevailing party."],[0,"(e) Construction"],[0,"Nothing in this section shall restrict any right which any person may have under any statute or common law."],[0,"(f) Venue; service of process"],[0,"Any civil action brought under subsection (a) in a district court of the United States may be brought in the district in which the defendant is found, is an inhabitant, or transacts business or wherever venue is proper under section 1391 of title 28. Process in such an action may be served in any district in which the defendant is an inhabitant or in which the defendant may be found."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/6104?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6104. Actions by private persons","tname":"Commerce and Trade","by":{"2":"19"}},{"t":"usc","label":"20 U.S.C. § 1617","url":"https://www.law.cornell.edu/uscode/text/20/1617","op":1,"ar":3,"tname":"Education","by":{"2":"12, 18"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","by":{"2":"3"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(a)(1)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"2":"12, 27","3":"10"}},{"t":"usc","label":"33 U.S.C. § 1910","url":"https://www.law.cornell.edu/uscode/text/33/1910","by":{"2":"19"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","by":{"2":"3"}},{"t":"usc","label":"42 U.S.C. § 2000cc","url":"https://www.law.cornell.edu/uscode/text/42/2000cc","by":{"2":"3"}},{"t":"usc","label":"49 U.S.C. § 30171","url":"https://www.law.cornell.edu/uscode/text/49/30171","by":{"2":"19"}},{"t":"usc","label":"49 U.S.C. § 60129","url":"https://www.law.cornell.edu/uscode/text/49/60129","subs":["(B)"],"by":{"2":"19"}},{"t":"law","label":"Telemarketing and Consumer Fraud and Abuse Prevention Act, Pub. L. No. 103-297","url":"https://www.govinfo.gov/link/statute/108/1545","by":{"2":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(a)"],"by":{"2":"27"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)(5)"],"by":{"2":"38"}},{"t":"case","label":"Brotherhood of Maintenance of Way Emps. v. Chicago & Nw. Transp. Co.","cite":"827 F.2d 330","y":1987,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/827/330/","by":{"3":"20"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"sum":"The District Court properly invoked its inherent power in assessing as a sanction for Chambers' bad-faith conduct the attorney's fees and related expenses paid by NASCO.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"De Jesus Nazario v. Morris Rodriguez","cite":"554 F.3d 196","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/554/196/","sum":"Holding the plaintiff’s “relationship with the defendants has changed in the requisite enduring manner”.","sumSrc":"brief:3","by":{"3":"14"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Exxon Mobil Corp. v. Allapattah Servs., Inc.","cite":"545 U.S. 546","y":2005,"id":"2004/04-70","sc":1,"sum":"The Court ruled that as long one plaintiff meets the amount-in-controversy requirement for federal jurisdiction, Section 1367 authorizes federal courts to exercise supplemental jurisdiction over related claims even if they do not meet the requirement.","sumSrc":"Oyez","by":{"3":"8"}},{"t":"case","label":"Federal Bureau of Investigation v. Fikre","cite":"601 U.S. 234","y":2024,"id":"2023/22-1178","sc":1,"op":1,"sum":"The Government failed to meet its burden to demonstrate that Mr. Fikre’s removal from the Government’s No Fly List mooted his 42 U. S. C. §1983 case because its declaration did not disclose the conduct that landed Mr. Fikre on the No Fly List and did not ensure that he would not be placed back on the list for engaging in the same or similar conduct in the future.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"22"}},{"t":"case","label":"Fleming v. Gutierrez","cite":"785 F.3d 442","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/442/","op":1,"by":{"3":"20"}},{"t":"case","label":"George v. McDonough","cite":"596 U.S. 740","y":2022,"id":"2021/21-234","sc":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"4"}},{"t":"case","label":"Marceaux v. Lafayette City-Par. Consol. Gov’t","cite":"731 F.3d 488","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/731/488/","by":{"3":"14"}},{"t":"case","label":"MCI Telecomms. Corp. v. American Tel. & Tel. Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"New York State Rifle & Pistol Ass’n, Inc. v. City of New York","cite":"590 U.S. 336","y":2020,"id":"2019/18-280","sc":1,"sum":"A case in which the Court was asked to decide whether New York City’s ban on transporting a licensed, locked, and unloaded handgun to a home or shooting range outside city limits is consistent with the Second Amendment, the Commerce Clause, and the constitutional right to travel.","sumSrc":"Oyez","by":{"3":"22, 23"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"3":"4"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"SecurityPoint Holdings, Inc. v. Transportation Sec. Admin.","cite":"836 F.3d 32","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/836/32/","by":{"3":"7"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"3":"10"}}]};